import base64,io,tarfile,pathlib,hashlib,json,os
raw=base64.b64decode('')
assert hashlib.sha256(raw).hexdigest()=='c59a0b442c9e8f1586b402354ce883b7db69f16023edfa4d461f9cf7c74266e4'
r=pathlib.Path('/dataset/shaoshitong/search-r1-rl/bapo-fresh200-safety-r2-20261006')
assert os.uname().nodename=='h100-16' and not r.exists() and not r.is_symlink()
r.mkdir(mode=0o700)
for name in ('logs','tools','scheduler-head'): (r/name).mkdir(mode=0o700)
(r/'source-expected.txt').write_text('8e01320bd4ba06f5b64cb6a3164373e6f25f35f7\n')
with tarfile.open(fileobj=io.BytesIO(raw),mode='r:')as t:
 for item in t.getmembers():
  p=pathlib.PurePosixPath(item.name)
  assert item.isfile() and ((len(p.parts)==2 and p.parts[0]=='tools') or item.name=='logs/tools-manifest.json') and '..' not in p.parts
  with (r/item.name).open('xb')as f:f.write(t.extractfile(item).read())
m=json.loads((r/'logs/tools-manifest.json').read_text());assert set(m['files'])=={p.name for p in (r/'tools').iterdir()}
assert all(hashlib.sha256((r/'tools'/n).read_bytes()).hexdigest()==h for n,h in m['files'].items())
print(json.dumps(dict(host=os.uname().nodename,source_commit=m['source_commit'],tools_manifest_sha256=hashlib.sha256((r/'logs/tools-manifest.json').read_bytes()).hexdigest(),scope='HEAD_SUBMIT_CODE_ONLY_NO_JOB_SUBMITTED')))
